    EZTR_Basic_ReplaceText(0x2328, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "Pas d'utilisation de masques dans " "\x11" "la boutique! Nous avons eu des " "\x11" "probl" "\x9C" "mes avec " "\x9B" "a dans le pass" "\x9D" "..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2329, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Kafei!" "\x11" "Nonononon, jamais vu ce gamin!!!" "\x11" "S" "\x9D" "rieusement! C'est vrai!!!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232A, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "Si tu portes " "\x9B" "a, tu ne pourras " "\x11" "jamais dormir! Je ne plaisante pas!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232B, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "H" "\x9D" ", c'est sympa..." "\x11" "\x13" "\x13" "\x12" "Peut-" "\x9E" "tre que je vais l'emporter" "\x11" "dans ma boutique! " "\x11" "Si, s" "\x9D" "rieux!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232C, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Ce n'est pas \"r" "\x9D" "serv" "\x9D" " aux " "\x11" "membres\" ici, alors enl" "\x9C" "ve " "\x9B" "a." "\x11" "Je ne plaisante pas!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232D, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x52" "C'est bien pour un gamin de ton " "\x11" "\x99" "ge. Livrer est un m" "\x9D" "tier difficile." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232E, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x52" "Oh! A qui?" "\x11" "F" "\x9D" "licitations!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x232F, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "Mon " "\x9D" "choppe est petite, alors ne" "\x11" "danse pas la gigue dedans!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2330, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "En voil" "\x97" " un curieux couvre-chef... " "\x11" "Enl" "\x9C" "ve-le..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2331, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Bizarre!" "\x11" "J'" "\x9D" "tais s" "\xAB" "r que quelqu'un " "\x9D" "tait " "\x11" "entr" "\x9D" "." "\x11" "\x12" "Bon, je dois me pr" "\x9D" "parer pour le" "\x11" "service de nuit." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2332, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "Ne va pas mener une parade dans " "\x11" "un petit endroit comme celui-ci." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2333, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x53" "Attention! Ne va pas te faire " "\x11" "exploser la t" "\x9E" "te ici. S" "\x9D" "rieux!" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2334, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Nan, j'connais pas ce gamin. Et le " "\x11" "chef est pas l" "\x97" ", alors je peux pas " "\x11" "t'aider." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2335, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6C" "Euh, " "\x9B" "a me g" "\x9E" "ne de porter " "\x9B" "a..." "\x11" "Je crois que je ne vais pas " "\x9E" "tre " "\x11" "membre..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2336, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Je suis venu gagner des places " "\x11" "de concert. Vous n'avez rien pour " "\x11" "moi?" "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2337, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6D" "Ahh, moi aussi j'voudrais trouver" "\x11" "une copine et me marier bient" "\xA7" "t..." "\xE0" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2338, 0x00, 0x30, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x6D" "Whoa! C'est un cr" "\x99" "ne? Ca, c'est" "\x11" "vraiment cool!" "\xE0" "\xBF" "", NULL);
