    EZTR_Basic_ReplaceText(0x2911, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x0A" "Oh, es-tu endormi?" "\x11" "\x13" "\x13" "\x12" "Cette histoire " "\x9D" "tait un peu trop" "\x11" "longue pour ce pauvre Tortus." "\x11" "\x13" "\x12" "Ne t'inqui" "\x9C" "te pas, tu l'entendras" "\x11" "une autre fois." "\xBF" "", NULL);
