    EZTR_Basic_ReplaceText(0x2919, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Nous avons " "\x9D" "chang" "\x9D" " nos voeux," "\x11" "nous formons un " "\x01" "couple " "\x00" "d" "\x9D" "sormais." "\xBF" "", NULL);
