    EZTR_Basic_ReplaceText(0x292A, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x59" "Doo-doo-doooo..." "\x11" "Ne leur parle pas maintenant. " "\x11" "\x13" "\x12" "Elles n'ont pas encore fini leur " "\x11" "nouvelle danse pour le carnaval." "\x11" "Doo-da-daa..." "\x11" "\x12" "La chanson est termin" "\x9D" "e." "\xE0" "\xBF" "", NULL);
