    EZTR_Basic_ReplaceText(0x2931, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "\x1E" "\x69" "\x80" "Pourquoi...? Pourquoi le chien...?" "\x11" "Pourquoi " "\x9D" "tait-il le chef?!? Est-ce" "\x11" "que quelque chose n'allait pas " "\x11" "avec moi? Ah l" "\x97" " l" "\x97" "..." "\x19" "\xBF" "", NULL);
    EZTR_Basic_ReplaceText(0x2932, 0x00, 0x00, 0xFE, 0xFFFF, 0xFFFF, 0xFFFF, false, "" "Oh, ce chien " "\x9D" "tait un chef de " "\x11" "troupe extraordinaire! Il avait " "\x11" "toujours une troupe de stars, " "\x11" "quels que soient les animaux..." "\x19" "\xBF" "", NULL);
